def container_env(cfg: Config) -> dict[str, str]:
    env = {"PATH": DEFAULT_PATH, "HOME": "/root", "HOSTNAME": cfg.hostname, "TERM": os.environ.get("TERM", "xterm")}
    for item in cfg.env:
        k, sep, v = item.partition("=")
        if not sep or not k:
            raise ValueError(f"--env needs KEY=VALUE, got {item!r}")
        env[k] = v
    return env

# real, minibox/libc.py
def libc() -> ctypes.CDLL:
    global _libc
    if _libc is None:
        # Try the glibc soname first: ctypes.util.find_library runs a subprocess (ldconfig), and
        # inside the container that extra fork would take PID 2 before the user's command does.
        try:
            _libc = ctypes.CDLL("libc.so.6", use_errno=True)
        except OSError:
            _libc = ctypes.CDLL(ctypes.util.find_library("c"), use_errno=True)
    return _libc

